INSERT INTO public.movies (id, title, year, poster, backdrop, rating, rating_count, runtime, genres, director, "cast", plot, release_date) VALUES
('1', 'The Shawshank Redemption', 1994, 'https://images.unsplash.com/photo-1440404653325-ab127d49abc1?w=300&h=450&fit=crop', 'https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?w=1920&h=1080&fit=crop', 9.3, 2847291, 142, ARRAY['Drama'], 'Frank Darabont', ARRAY['Tim Robbins', 'Morgan Freeman', 'Bob Gunton', 'William Sadler'], 'Over the course of several years, two convicts form a friendship, seeking consolation and, eventually, redemption through basic compassion.', '1994-09-23'),
('2', 'The Godfather', 1972, 'https://images.unsplash.com/photo-1594909122845-11baa439b7bf?w=300&h=450&fit=crop', 'https://images.unsplash.com/photo-1536440136628-849c177e76a1?w=1920&h=1080&fit=crop', 9.2, 1987654, 175, ARRAY['Crime', 'Drama'], 'Francis Ford Coppola', ARRAY['Marlon Brando', 'Al Pacino', 'James Caan', 'Diane Keaton'], 'The aging patriarch of an organized crime dynasty transfers control of his clandestine empire to his reluctant youngest son.', '1972-03-24'),
('3', 'The Dark Knight', 2008, 'https://images.unsplash.com/photo-1531259683007-016a7b628fc3?w=300&h=450&fit=crop', 'https://images.unsplash.com/photo-1534809027769-b00d750a6bac?w=1920&h=1080&fit=crop', 9.0, 2765432, 152, ARRAY['Action', 'Crime', 'Drama'], 'Christopher Nolan', ARRAY['Christian Bale', 'Heath Ledger', 'Aaron Eckhart', 'Michael Caine'], 'When the menace known as the Joker wreaks havoc and chaos on the people of Gotham, Batman must accept one of the greatest psychological and physical tests of his ability to fight injustice.', '2008-07-18'),
('4', 'Pulp Fiction', 1994, 'https://images.unsplash.com/photo-1478720568477-152d9b164e26?w=300&h=450&fit=crop', 'https://images.unsplash.com/photo-1485846234645-a62644f84728?w=1920&h=1080&fit=crop', 8.9, 2156789, 154, ARRAY['Crime', 'Drama'], 'Quentin Tarantino', ARRAY['John Travolta', 'Uma Thurman', 'Samuel L. Jackson', 'Bruce Willis'], 'The lives of two mob hitmen, a boxer, a gangster and his wife, and a pair of diner bandits intertwine in four tales of violence and redemption.', '1994-10-14'),
('5', 'Inception', 2010, 'https://images.unsplash.com/photo-1518676590629-3dcbd9c5a5c9?w=300&h=450&fit=crop', 'https://images.unsplash.com/photo-1500462918059-b1a0cb512f1d?w=1920&h=1080&fit=crop', 8.8, 2456123, 148, ARRAY['Action', 'Adventure', 'Sci-Fi'], 'Christopher Nolan', ARRAY['Leonardo DiCaprio', 'Joseph Gordon-Levitt', 'Elliot Page', 'Tom Hardy'], 'A thief who steals corporate secrets through the use of dream-sharing technology is given the inverse task of planting an idea into the mind of a C.E.O.', '2010-07-16'),
('6', 'Fight Club', 1999, 'https://images.unsplash.com/photo-1574375927938-d5a98e8ffe85?w=300&h=450&fit=crop', 'https://images.unsplash.com/photo-1626814026160-2237a95fc5a0?w=1920&h=1080&fit=crop', 8.8, 2234567, 139, ARRAY['Drama'], 'David Fincher', ARRAY['Brad Pitt', 'Edward Norton', 'Helena Bonham Carter', 'Meat Loaf'], 'An insomniac office worker and a devil-may-care soap maker form an underground fight club that evolves into much more.', '1999-10-15'),
('7', 'Forrest Gump', 1994, 'https://images.unsplash.com/photo-1616530940355-351fabd9524b?w=300&h=450&fit=crop', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=1920&h=1080&fit=crop', 8.8, 2123456, 142, ARRAY['Drama', 'Romance'], 'Robert Zemeckis', ARRAY['Tom Hanks', 'Robin Wright', 'Gary Sinise', 'Sally Field'], 'The presidencies of Kennedy and Johnson, the Vietnam War, the Watergate scandal and other historical events unfold from the perspective of an Alabama man with an IQ of 75.', '1994-07-06'),
('8', 'The Matrix', 1999, 'https://images.unsplash.com/photo-1526374965328-7f61d4dc18c5?w=300&h=450&fit=crop', 'https://images.unsplash.com/photo-1515879218367-8466d910aaa4?w=1920&h=1080&fit=crop', 8.7, 1987654, 136, ARRAY['Action', 'Sci-Fi'], 'The Wachowskis', ARRAY['Keanu Reeves', 'Laurence Fishburne', 'Carrie-Anne Moss', 'Hugo Weaving'], 'When a beautiful stranger leads computer hacker Neo to a forbidding underworld, he discovers the shocking truth--the life he knows is the elaborate deception of an evil cyber-intelligence.', '1999-03-31'),
('9', 'Interstellar', 2014, 'https://images.unsplash.com/photo-1446776811953-b23d57bd21aa?w=300&h=450&fit=crop', 'https://images.unsplash.com/photo-1419242902214-272b3f66ee7a?w=1920&h=1080&fit=crop', 8.7, 1876543, 169, ARRAY['Adventure', 'Drama', 'Sci-Fi'], 'Christopher Nolan', ARRAY['Matthew McConaughey', 'Anne Hathaway', 'Jessica Chastain', 'Michael Caine'], 'A team of explorers travel through a wormhole in space in an attempt to ensure humanity''s survival.', '2014-11-07'),
('10', 'Goodfellas', 1990, 'https://images.unsplash.com/photo-1585951237313-1979e4df7385?w=300&h=450&fit=crop', 'https://images.unsplash.com/photo-1504297050568-910d24c426d3?w=1920&h=1080&fit=crop', 8.7, 1234567, 145, ARRAY['Biography', 'Crime', 'Drama'], 'Martin Scorsese', ARRAY['Robert De Niro', 'Ray Liotta', 'Joe Pesci', 'Lorraine Bracco'], 'The story of Henry Hill and his life in the mob, covering his relationship with his wife Karen Hill and his mob partners Jimmy Conway and Tommy DeVito in the Italian-American crime syndicate.', '1990-09-19'),
('11', 'Parasite', 2019, 'https://images.unsplash.com/photo-1536440136628-849c177e76a1?w=300&h=450&fit=crop', 'https://images.unsplash.com/photo-1517604931442-7e0c8ed2963c?w=1920&h=1080&fit=crop', 8.5, 876543, 132, ARRAY['Drama', 'Thriller'], 'Bong Joon Ho', ARRAY['Song Kang-ho', 'Lee Sun-kyun', 'Cho Yeo-jeong', 'Choi Woo-shik'], 'Greed and class discrimination threaten the newly formed symbiotic relationship between the wealthy Park family and the destitute Kim clan.', '2019-05-30'),
('12', 'The Silence of the Lambs', 1991, 'https://images.unsplash.com/photo-1509281373149-e957c6296406?w=300&h=450&fit=crop', 'https://images.unsplash.com/photo-1478720568477-152d9b164e26?w=1920&h=1080&fit=crop', 8.6, 1456789, 118, ARRAY['Crime', 'Drama', 'Thriller'], 'Jonathan Demme', ARRAY['Jodie Foster', 'Anthony Hopkins', 'Scott Glenn', 'Ted Levine'], 'A young F.B.I. cadet must receive the help of an incarcerated and manipulative cannibal killer to help catch another serial killer.', '1991-02-14')
