INSERT INTO public.reviews (id, movie_id, user_id, user_name, rating, title, content, helpful, created_at) VALUES
('r1', '1', 'u1', 'MovieBuff42', 10, 'A masterpiece of cinema', 'This film is nothing short of perfection. The story of hope and friendship in the darkest of places resonates deeply. Morgan Freeman''s narration is iconic, and Tim Robbins delivers a career-defining performance. The ending is one of the most satisfying in film history.', 2341, '2024-01-15T00:00:00Z'),
('r2', '1', 'u2', 'CinemaLover', 9, 'Timeless storytelling', 'Watched this for the tenth time and it still hits different. The pacing is perfect, the characters are memorable, and the themes of hope and redemption are universal. A must-watch for anyone who appreciates quality filmmaking.', 1876, '2024-02-20T00:00:00Z'),
('r3', '2', 'u3', 'ClassicFilmFan', 10, 'The definitive crime drama', 'Coppola''s masterwork set the standard for all crime films that followed. Brando''s performance is legendary, and the transformation of Michael Corleone is one of the greatest character arcs ever written. Essential viewing.', 3456, '2023-11-08T00:00:00Z'),
('r4', '3', 'u4', 'ActionHero', 10, 'Heath Ledger is unforgettable', 'This isn''t just a superhero movie - it''s a crime thriller that happens to feature Batman. Heath Ledger''s Joker is the greatest villain performance ever captured on film. The practical effects and IMAX sequences are breathtaking.', 4521, '2024-03-12T00:00:00Z'),
('r5', '5', 'u5', 'SciFiGeek', 9, 'Mind-bending brilliance', 'Nolan crafts a puzzle box of a film that rewards multiple viewings. The dream-within-a-dream concept is executed flawlessly, and the ensemble cast is stellar. The hallway fight scene is one of the most creative action sequences ever filmed.', 2987, '2024-01-28T00:00:00Z')
